-- 024_telecom_segments_columns.sql
-- Telecom segments, part 1 of 3 (BUSINESS_RULES 13D, TELECOM_SEGMENTS_BUILD_PLAN.md). GENERATED by server/src/db/gen/telecom-segments-sql.ts; do not edit.
-- Telecom is split into 8 segments (dialog/mobitel/airtel/hutch x cards/reloads). This migration:
--   1. adds a stored `segment` column (domain-checked) to the eleven tables that are not rebuilt, and categories.provider_id;
--   2. creates the view v_product_segment(product_id, book, segment) (a product's segment comes from its category's provider);
--   3. marks every existing Telecom row 'legacy' (Shop / Ice Cream rows stay NULL). Only the segment column is written; no money, date or
--      status column is touched. cash_entries is append-only, so its no-update trigger is dropped around the backfill and re-created from
--      its exact stored text (a test compares sqlite_master.sql before and after);
--   4. makes the opening balance unique per scope (book + segment + fund);
--   5. adds the INSERT-rule and immutability triggers, re-creates trg_cash_entries_reversal_mirror with the segment compared, and adds the
--      category-provider / product triggers.
-- The rebuilt tables (daily_closings, cash_transfers, sales) are handled by 025; the closed-day triggers and the cross-table consistency
-- triggers by 026. The runner executes this file in one transaction with foreign_keys ON. Forward-only.

CREATE TEMP TABLE _mig024_before (tbl TEXT NOT NULL, n INTEGER NOT NULL, ids INTEGER NOT NULL, money INTEGER NOT NULL);
INSERT INTO _mig024_before SELECT 'cash_entries', COUNT(*), TOTAL(id), TOTAL(amount_cents) FROM cash_entries;
INSERT INTO _mig024_before SELECT 'cash_counts', COUNT(*), TOTAL(id), 0 FROM cash_counts;
INSERT INTO _mig024_before SELECT 'capital_entries', COUNT(*), TOTAL(id), 0 FROM capital_entries;
INSERT INTO _mig024_before SELECT 'owner_drawings', COUNT(*), TOTAL(id), 0 FROM owner_drawings;
INSERT INTO _mig024_before SELECT 'expenses', COUNT(*), TOTAL(id), 0 FROM expenses;
INSERT INTO _mig024_before SELECT 'purchases', COUNT(*), TOTAL(id), 0 FROM purchases;
INSERT INTO _mig024_before SELECT 'stock_losses', COUNT(*), TOTAL(id), 0 FROM stock_losses;
INSERT INTO _mig024_before SELECT 'stocktakes', COUNT(*), TOTAL(id), 0 FROM stocktakes;
INSERT INTO _mig024_before SELECT 'reload_sales', COUNT(*), TOTAL(id), 0 FROM reload_sales;
INSERT INTO _mig024_before SELECT 'ezcash_sales', COUNT(*), TOTAL(id), 0 FROM ezcash_sales;
INSERT INTO _mig024_before SELECT 'telecom_topups', COUNT(*), TOTAL(id), 0 FROM telecom_topups;
CREATE TEMP TABLE _mig024_trg AS SELECT name, sql FROM sqlite_master WHERE name = 'trg_cash_entries_no_update';
CREATE TEMP TABLE _mig024_objs AS SELECT type, name FROM sqlite_master WHERE type IN ('index','trigger','view') AND name NOT LIKE 'sqlite_autoindex%';

-- 1. columns
ALTER TABLE cash_entries ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy'));
ALTER TABLE cash_counts ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy'));
ALTER TABLE capital_entries ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy'));
ALTER TABLE owner_drawings ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy'));
ALTER TABLE expenses ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'dialog_reloads', 'mobitel_cards', 'mobitel_reloads', 'airtel_cards', 'airtel_reloads', 'hutch_cards', 'hutch_reloads', 'legacy'));
ALTER TABLE purchases ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'mobitel_cards', 'airtel_cards', 'hutch_cards', 'legacy'));
ALTER TABLE stock_losses ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'mobitel_cards', 'airtel_cards', 'hutch_cards', 'legacy'));
ALTER TABLE stocktakes ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_cards', 'mobitel_cards', 'airtel_cards', 'hutch_cards', 'legacy'));
ALTER TABLE reload_sales ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_reloads', 'mobitel_reloads', 'airtel_reloads', 'hutch_reloads', 'legacy'));
ALTER TABLE ezcash_sales ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_reloads', 'mobitel_reloads', 'airtel_reloads', 'hutch_reloads', 'legacy'));
ALTER TABLE telecom_topups ADD COLUMN segment TEXT CHECK (segment IS NULL OR segment IN ('dialog_reloads', 'mobitel_reloads', 'airtel_reloads', 'hutch_reloads', 'legacy'));
ALTER TABLE categories ADD COLUMN provider_id INTEGER REFERENCES reload_providers(id);

-- 2. the product -> segment view (Telecom: the category's provider + _cards, or 'legacy' while the category has no provider)
CREATE VIEW v_product_segment AS
SELECT p.id AS product_id,
       p.book AS book,
       CASE WHEN p.book <> 'telecom' THEN NULL
            WHEN rp.id IS NULL THEN 'legacy'
            ELSE lower(rp.name) || '_cards' END AS segment
  FROM products p
  JOIN categories c ON c.id = p.category_id
  LEFT JOIN reload_providers rp ON rp.id = c.provider_id;

CREATE INDEX idx_categories_provider ON categories(provider_id);
CREATE INDEX idx_cash_entries_book_segment_date ON cash_entries(book, segment, business_date);

-- 3. backfill: every existing Telecom row is legacy; only the segment column is written
DROP TRIGGER trg_cash_entries_no_update;
UPDATE cash_entries SET segment = 'legacy' WHERE book = 'telecom';
CREATE TRIGGER trg_cash_entries_no_update BEFORE UPDATE ON cash_entries
BEGIN
  SELECT RAISE(ABORT, 'cash_entries is append-only');
END;
UPDATE cash_counts SET segment = 'legacy' WHERE book = 'telecom';
UPDATE capital_entries SET segment = 'legacy' WHERE book = 'telecom';
UPDATE owner_drawings SET segment = 'legacy' WHERE book = 'telecom';
UPDATE expenses SET segment = 'legacy' WHERE book = 'telecom';
UPDATE purchases SET segment = 'legacy' WHERE book = 'telecom';
UPDATE stock_losses SET segment = 'legacy' WHERE book = 'telecom';
UPDATE stocktakes SET segment = 'legacy' WHERE book = 'telecom';
UPDATE reload_sales SET segment = 'legacy';
UPDATE ezcash_sales SET segment = 'legacy';
UPDATE telecom_topups SET segment = 'legacy';

-- 4. one posted opening balance per scope (book + segment [+ fund]); the existing Telecom opening balance is the legacy one
DROP INDEX ux_capital_opening_balance;
CREATE UNIQUE INDEX ux_capital_opening_balance ON capital_entries(book, COALESCE(segment, ''), COALESCE(fund, ''))
  WHERE kind = 'opening_balance' AND status = 'posted';

-- 5. rules: telecom rows need a segment, other books forbid one, legacy is refused on INSERT; the segment never changes
CREATE TRIGGER trg_cash_entries_segment_insert
BEFORE INSERT ON cash_entries
WHEN (NEW.book = 'telecom') <> (NEW.segment IS NOT NULL)
  OR (NEW.segment = 'legacy' AND NOT (
        (NEW.reverses_entry_id IS NOT NULL AND (SELECT o.segment FROM cash_entries o WHERE o.id = NEW.reverses_entry_id) IS 'legacy')
     OR (NEW.ref_table = 'sales_returns' AND EXISTS (SELECT 1 FROM sales_returns r JOIN sales s ON s.id = r.sale_id
                                                      WHERE r.id = NEW.ref_id AND s.segment IS 'legacy'))
     OR (NEW.ref_table = 'purchase_returns' AND EXISTS (SELECT 1 FROM purchase_returns r JOIN purchases p ON p.id = r.purchase_id
                                                         WHERE r.id = NEW.ref_id AND p.segment IS 'legacy'))))
BEGIN
  SELECT RAISE(ABORT, CASE WHEN NEW.segment = 'legacy' THEN 'SEGMENT_LEGACY_REFUSED'
                           WHEN NEW.segment IS NULL THEN 'SEGMENT_REQUIRED' ELSE 'SEGMENT_NOT_ALLOWED' END);
END;

CREATE TRIGGER trg_cash_entries_segment_immutable
BEFORE UPDATE OF segment ON cash_entries
WHEN NEW.segment IS NOT OLD.segment
BEGIN
  SELECT RAISE(ABORT, 'SEGMENT_READ_ONLY');
END;

