CREATE TEMP TABLE _mig024_guard (ok INTEGER NOT NULL CHECK (ok = 1));
INSERT INTO _mig024_guard SELECT CASE WHEN
  (SELECT COUNT(*) FROM cash_entries) = (SELECT n FROM _mig024_before WHERE tbl = 'cash_entries')
 AND   (SELECT TOTAL(id) FROM cash_entries) = (SELECT ids FROM _mig024_before WHERE tbl = 'cash_entries')
 AND   NOT EXISTS (SELECT 1 FROM cash_entries WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
 AND   (SELECT COUNT(*) FROM cash_counts) = (SELECT n FROM _mig024_before WHERE tbl = 'cash_counts')
 AND   (SELECT TOTAL(id) FROM cash_counts) = (SELECT ids FROM _mig024_before WHERE tbl = 'cash_counts')
 AND   NOT EXISTS (SELECT 1 FROM cash_counts WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
 AND   (SELECT COUNT(*) FROM capital_entries) = (SELECT n FROM _mig024_before WHERE tbl = 'capital_entries')
 AND   (SELECT TOTAL(id) FROM capital_entries) = (SELECT ids FROM _mig024_before WHERE tbl = 'capital_entries')
 AND   NOT EXISTS (SELECT 1 FROM capital_entries WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
 AND   (SELECT COUNT(*) FROM owner_drawings) = (SELECT n FROM _mig024_before WHERE tbl = 'owner_drawings')
 AND   (SELECT TOTAL(id) FROM owner_drawings) = (SELECT ids FROM _mig024_before WHERE tbl = 'owner_drawings')
 AND   NOT EXISTS (SELECT 1 FROM owner_drawings WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
