 AND   (SELECT TOTAL(id) FROM expenses) = (SELECT ids FROM _mig024_before WHERE tbl = 'expenses')
 AND   NOT EXISTS (SELECT 1 FROM expenses WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
 AND   (SELECT COUNT(*) FROM purchases) = (SELECT n FROM _mig024_before WHERE tbl = 'purchases')
 AND   (SELECT TOTAL(id) FROM purchases) = (SELECT ids FROM _mig024_before WHERE tbl = 'purchases')
 AND   NOT EXISTS (SELECT 1 FROM purchases WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
 AND   (SELECT COUNT(*) FROM stock_losses) = (SELECT n FROM _mig024_before WHERE tbl = 'stock_losses')
 AND   (SELECT TOTAL(id) FROM stock_losses) = (SELECT ids FROM _mig024_before WHERE tbl = 'stock_losses')
 AND   NOT EXISTS (SELECT 1 FROM stock_losses WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
