 AND   NOT EXISTS (SELECT 1 FROM stocktakes WHERE (book = 'telecom') <> (segment IS NOT NULL) OR (book = 'telecom' AND segment <> 'legacy'))
 AND   (SELECT COUNT(*) FROM reload_sales) = (SELECT n FROM _mig024_before WHERE tbl = 'reload_sales')
 AND   (SELECT TOTAL(id) FROM reload_sales) = (SELECT ids FROM _mig024_before WHERE tbl = 'reload_sales')
 AND   NOT EXISTS (SELECT 1 FROM reload_sales WHERE segment IS NOT 'legacy')
 AND   (SELECT COUNT(*) FROM ezcash_sales) = (SELECT n FROM _mig024_before WHERE tbl = 'ezcash_sales')
 AND   (SELECT TOTAL(id) FROM ezcash_sales) = (SELECT ids FROM _mig024_before WHERE tbl = 'ezcash_sales')
 AND   NOT EXISTS (SELECT 1 FROM ezcash_sales WHERE segment IS NOT 'legacy')
 AND   (SELECT COUNT(*) FROM telecom_topups) = (SELECT n FROM _mig024_before WHERE tbl = 'telecom_topups')
 AND   (SELECT TOTAL(id) FROM telecom_topups) = (SELECT ids FROM _mig024_before WHERE tbl = 'telecom_topups')
 AND   NOT EXISTS (SELECT 1 FROM telecom_topups WHERE segment IS NOT 'legacy')
 AND   (SELECT TOTAL(amount_cents) FROM cash_entries) = (SELECT money FROM _mig024_before WHERE tbl = 'cash_entries')
 AND   (SELECT sql FROM sqlite_master WHERE name = 'trg_cash_entries_no_update') IS (SELECT sql FROM _mig024_trg)
 AND   NOT EXISTS (SELECT 1 FROM categories WHERE provider_id IS NOT NULL)
 AND   NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check)
 AND   NOT EXISTS (SELECT 1 FROM _mig024_objs o WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = o.type AND m.name = o.name))
 AND   NOT EXISTS (SELECT 1 FROM _mig024_new w WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = w.type AND m.name = w.name))
 AND   (SELECT COUNT(*) FROM sqlite_master WHERE type IN ('index','trigger','view') AND name NOT LIKE 'sqlite_autoindex%') = (SELECT COUNT(*) FROM _mig024_objs) + (SELECT COUNT(*) FROM _mig024_new)
  THEN 1 ELSE 0 END;

